<?php require_once __DIR__ . '/layout.php';
$id=(int)($_GET['id']??0); $users=load_data('users'); $user=$id ? (find_by_id($users,$id) ?: []) : []; $user += ['full_name'=>'','department'=>'','office'=>'','phone'=>''];
if($_SERVER['REQUEST_METHOD']==='POST'){ $item=['id'=>$id ?: next_id($users),'full_name'=>trim($_POST['full_name']),'department'=>trim($_POST['department']),'office'=>trim($_POST['office']),'phone'=>trim($_POST['phone'])]; if($id){ foreach($users as &$u){ if((int)$u['id']===$id){$u=$item; break;} } } else $users[]=$item; save_data('users',$users); redirect('users.php'); }
page_header($id?'Edit user':'Add user','users'); ?><div class="card"><h2><?= $id?'Edit user':'Add user' ?></h2><form method="post"><div class="form-grid"><div><label>Full name</label><input name="full_name" required value="<?= h($user['full_name']) ?>"></div><div><label>Department</label><input name="department" value="<?= h($user['department']) ?>"></div><div><label>Office</label><input name="office" value="<?= h($user['office']) ?>"></div><div><label>Phone</label><input name="phone" value="<?= h($user['phone']) ?>"></div></div><button class="btn">Save</button></form></div><?php page_footer(); ?>
